import React from "react";
import { CheckCircle } from "lucide-react";

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {

  // ================= HYBRID =================
  const hybridSteps = [
    {
      label: "Ephemeral Agreement",
      sub: "X25519",
      details: ["Generate key", "Exchange values"]
    },
    {
      label: "Encapsulate",
      sub: "Kyber",
      details: ["Shared secret", "Ciphertext"]
    },
    {
      label: "HKDF",
      sub: "SHA-256",
      details: ["Mix salt", "Expand key"]
    },
    {
      label: "AES Encrypt",
      sub: "GCM",
      details: ["Encrypt", "Tag"]
    },
    {
      label: "Upload",
      sub: "MinIO",
      details: ["Pack", "Store"]
    }
  ];

  // ================= RSA =================
  const rsaSteps = [
    {
      label: "Keypair",
      sub: "RSA-2048",
      details: ["Public key", "Private key"]
    },
    {
      label: "Padding",
      sub: "OAEP",
      details: ["Prepare"]
    },
    {
      label: "Encrypt",
      sub: "Mod Exp",
      details: ["Cipher"]
    },
    {
      label: "Build Blob",
      sub: "Meta",
      details: ["Headers"]
    },
    {
      label: "Upload",
      sub: "MinIO",
      details: ["Store"]
    }
  ];

  const steps = mode === "hybrid" ? hybridSteps : rsaSteps;

  const color =
    mode === "hybrid"
      ? "text-neon-green border-neon-green"
      : "text-purple-400 border-purple-400";

  const line =
    mode === "hybrid"
      ? "bg-neon-green"
      : "bg-purple-400";

  return (
    <div className="bg-black/40 p-10 rounded-xl border border-scifi-border">

      {/* MAIN ROW */}
      <div className="flex justify-between relative">

        {/* BASE LINE */}
        <div className="absolute top-6 left-0 w-full h-[2px] bg-gray-800"></div>

        {/* PROGRESS */}
        <div
          className={`absolute top-6 left-0 h-[2px] ${line}`}
          style={{
            width: `${(Math.max(currentStep - 1, 0) / (steps.length - 1)) * 100}%`
          }}
        />

        {steps.map((step, i) => {
          const active = currentStep >= i + 1;

          // alternate
          const isUp = i % 2 === 0;

          return (
            <div key={i} className="relative z-10 flex flex-col items-center w-40">

              {/* PARENT */}
              <div className={`w-12 h-12 rounded-full border-2 bg-black flex items-center justify-center ${active ? color : "border-gray-700 text-gray-700"}`}>
                {active ? <CheckCircle size={18}/> : <div className="w-2 h-2 bg-gray-600 rounded-full"/>}
              </div>

              {/* TITLE */}
              <div className="mt-2 text-center">
                <p className={`text-[11px] font-bold ${active ? "text-white" : "text-gray-600"}`}>
                  {step.label}
                </p>
                <p className="text-[10px] text-gray-500 font-mono">{step.sub}</p>
              </div>

              {/* BRANCH AREA */}
              <div className="relative mt-4">

                {step.details.map((d, k) => (
                  <div key={k} className="flex flex-col items-center absolute left-1/2"
                    style={{
                      transform: `translateX(${(k - (step.details.length - 1)/2) * 60}px)`
                    }}
                  >

                    {/* connector */}
                    <div className={`w-[2px] ${active ? line : "bg-gray-800"} ${isUp ? "h-10 -mt-16" : "h-10 mt-2"}`} />

                    {/* child node */}
                    <div className={`w-6 h-6 rounded-full border ${active ? color : "border-gray-700"} bg-black`} />

                    {/* text */}
                    <p className={`mt-2 text-[10px] font-mono ${mode === "hybrid" ? "text-neon-green" : "text-purple-300"}`}>
                      {d}
                    </p>
                  </div>
                ))}

              </div>

            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
